        id,
        fontId,
        name,
        settingsVersion: 1,
        settings: { ...settings, axes: { ...settings.axes } },
        sampleText,
        inheritSampleText,
        revision: 1,
        createdAt: now,
        updatedAt: now,
      };
      await fontDatabase.variants.add(row);
      return toVariant(row);
    }),
