import Dexie, { type Table } from "dexie";
import { MONOCHROME, type PalettePreset } from "./palettes/model.ts";
import type { FontMetadata, FontSource } from "./fonts/storage.ts";
import type { FontVariant } from "./variants/model.ts";

export interface FontRow {
  id: string;
  name: string;
  fileName: string;
  bytes: ArrayBuffer;
  metadata: FontMetadata;
  source: FontSource;
  addedAt: number;
}

export interface MetaRow {
  key: string;
  value: string;
}

export interface VariantRow {
  id: string;
  fontId: string;
  name: string;
  settingsVersion: 1;
  settings: FontVariant["settings"];
  sampleText: string;
  inheritSampleText?: boolean;
  revision: number;
  createdAt: number;
  updatedAt: number;
}

class FontLibraryDatabase extends Dexie {
  fonts!: Table<FontRow, string>;
  meta!: Table<MetaRow, string>;
  variants!: Table<VariantRow, string>;
  palettes!: Table<PalettePreset, number>;
  constructor() {
    super("font-library");
    this.version(1).stores({ fonts: "id, addedAt, source", meta: "key" });
    // Additive upgrade: fonts/meta carry over untouched, variants start empty.
    // The fontId index serves per-font variant queries; ordering is applied
    // deterministically (createdAt, id) at read time.
    this.version(2).stores({ fonts: "id, addedAt, source", meta: "key", variants: "id, fontId" });
    this.version(3).stores({ palettes: "++id" }).upgrade(async (tx) => {
      await tx.table("palettes").add(MONOCHROME);
      // Historical output profiles do not identify a defined palette.
      await tx.table("variants").toCollection().modify((row: VariantRow) => {
        row.settings.paletteId = MONOCHROME.id;
        row.settings.profile = "mono_1bit";
      });
    });
    this.on("populate", async (tx) => { await tx.table("palettes").add(MONOCHROME); });
  }
}

export const fontDatabase = new FontLibraryDatabase();

let databaseBlocked = false;
fontDatabase.on("blocked", () => {
  databaseBlocked = true;
});

export function isDatabaseBlocked(): boolean {
  return databaseBlocked;
}

export function errorName(error: unknown): string {
  return typeof error === "object" && error !== null && "name" in error
    ? String((error as { name: unknown }).name)
    : "";
}

// Reopen-and-retry for a database handle closed by a version upgrade in
// another tab; error mapping stays with the calling module so each error
// family keeps its own codes.
export async function runWithReopen<T>(operation: () => Promise<T>): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    if (errorName(error) !== "DatabaseClosedError") throw error;
    await fontDatabase.open();
    return await operation();
  }
}
// Reads renderer overrides as JSON on stdin; writes { policy, fingerprint }.
// Usage: node preview-policy-bridge.ts < request.json
import { resolveWorkingPreviewPolicy } from "../../src/app/renderer/preview-policy.ts";
import { fingerprintPreviewPolicy } from "../policy-fingerprint.ts";

const raw = await new Promise<string>((resolve, reject) => {
  let text = "";
  process.stdin.setEncoding("utf8");
  process.stdin.on("data", (chunk) => { text += chunk; });
  process.stdin.on("end", () => resolve(text));
  process.stdin.on("error", reject);
});

let input: Record<string, unknown>;
try {
  input = JSON.parse(raw || "{}");
} catch {
  console.error("preview-policy-bridge: stdin is not valid JSON.");
  process.exit(1);
}

function booleanField(value: unknown, name: string): boolean | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "boolean") {
    console.error(`preview-policy-bridge: ${name} must be a boolean.`);
    process.exit(1);
  }
  return value;
}

function stringField(value: unknown, name: string): string | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "string") {
    console.error(`preview-policy-bridge: ${name} must be a string.`);
    process.exit(1);
  }
  return value;
}

try {
  const policy = resolveWorkingPreviewPolicy({
    fitting: stringField(input.fitting, "fitting"),
    rasterization: stringField(input.rasterization, "rasterization"),
    diagonalFitting: booleanField(
      input.diagonalFitting ?? input.diagonal_fitting,
      "diagonal_fitting",
    ),
    dropout: stringField(input.dropout, "dropout"),
    includeStubs: booleanField(input.includeStubs ?? input.include_stubs, "include_stubs"),
    fontInstructions: booleanField(
      input.fontInstructions ?? input.font_instructions,
      "font_instructions",
    ),
  });
  process.stdout.write(JSON.stringify({
    policy,
    fingerprint: fingerprintPreviewPolicy(policy),
  }) + "\n");
} catch (error) {
  console.error(`preview-policy-bridge: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
}

//! Hobby edge (1)-(3) and pair-width (4)-(5) residuals.
//!
//! Callers supply their projection arithmetic to preserve signed-zero behavior.

use super::Sample;

pub(super) struct EdgeRows {
    pub(super) sum: Vec<f64>,
    pub(super) diff: Vec<f64>,
    pub(super) stretch: Vec<f64>,
    pub(super) bend: Vec<f64>,
}

/// Straight-edge position, stretch and bend residuals.
pub(super) fn edge_rows(
    points: &[[f64; 2]],
    height: f64,
    i: usize,
    j: usize,
    project: impl Fn(&Sample, [f64; 2], Option<&Sample>) -> Vec<f64>,
) -> Result<EdgeRows, ()> {
    let a = Sample::vertex(i);
    let b = Sample::vertex(j);
    let pa = a.point(points);
    let pb = b.point(points);
    let delta = [pb[0] - pa[0], pb[1] - pa[1]];
    let length = delta[0].hypot(delta[1]);
    if !(length > 0.0) {
        return Err(());
    }
    let tangent = [delta[0] / length, delta[1] / length];
    let normal = [-tangent[1], tangent[0]];
    let alpha1 = 1000.0 / height.powi(3);
    let ri = project(&a, normal, None);
    let rj = project(&b, normal, None);
    let sum: Vec<f64> = ri
        .iter()
        .zip(rj.iter())
        .map(|(x, y)| (x + y) * (alpha1 * length / 4.0).sqrt())
        .collect();
    let diff: Vec<f64> = rj
        .iter()
        .zip(ri.iter())
        .map(|(x, y)| (x - y) * (alpha1 * length / 12.0).sqrt())
        .collect();
    let scale = (25.0 * length / height).sqrt() / length;
    let stretch: Vec<f64> = project(&b, tangent, Some(&a))
        .iter()
        .map(|x| x * scale)
        .collect();
    let bend: Vec<f64> = rj
        .iter()
        .zip(ri.iter())
        .map(|(x, y)| (x - y) * scale)
        .collect();
    Ok(EdgeRows {
        sum,
        diff,
        stretch,
        bend,
    })
}

/// Signed relative-width error using twice the medial radius.
pub(super) fn pair_residual(
    points: &[[f64; 2]],
    a: &Sample,
    b: &Sample,
    arc: f64,
    medial: [f64; 2],
    project: impl Fn(&Sample, [f64; 2], Option<&Sample>) -> Vec<f64>,
) -> Result<(Vec<f64>, f64, [f64; 2]), ()> {
    if !(arc.is_finite() && arc > 0.0) {
        return Err(());
    }
    let pa = a.point(points);
    let pb = b.point(points);
    let chord = [pa[0] - pb[0], pa[1] - pb[1]];
    let distance = chord[0].hypot(chord[1]);
    if !(distance > 0.0) {
        return Err(());
    }
    let width = 2.0 * (pa[0] - medial[0]).hypot(pa[1] - medial[1]);
    let other = 2.0 * (pb[0] - medial[0]).hypot(pb[1] - medial[1]);
    if !(width > 0.0) || (width - other).abs() > 1e-12 + 1e-10 * other.abs() {
        return Err(());
    }
    let normal = [chord[0] / distance, chord[1] / distance];
    let tangent = [-normal[1], normal[0]];
    let mut error = project(a, normal, Some(b));
    for x in error.iter_mut() {
        *x /= -width;
    }
    Ok((error, width, tangent))
}

