    let font = fs::read(&font_path).map_err(|e| format!("cannot read font: {e}"))?;
    let checksum = format!("{:x}", Sha256::digest(&font));
    if job.provenance.expected_sha256 != checksum {
        return Err(format!(
            "font checksum mismatch: actual SHA-256 is {checksum}"
        ));
    }
