    if setup["status"] != "ok":
        stage = ("outside-overlap" if setup["status"] == "no-overlap"
                 else "degenerate-frame")
        return {"hit": None, "stage": stage, "tag": None,
                "status": setup["status"]}
    lo, hi, L0, O = setup["lo"], setup["hi"], setup["L0"], setup["O"]
    if not lo < t < hi:
        return {"hit": None, "stage": "outside-overlap", "tag": None,
                "status": "ok"}
